class TransactionContext(Generic[DatabaseT]):
    def __init__(self, executor: QueryExecutor, schema: Schema | None = None) -> None:
        self._executor = executor
        self._schema = schema
        self._connection: DatabaseConnection | None = None

    async def __aenter__(self) -> Pysely[DatabaseT]:
        driver = self._executor.driver
        if driver is None:
            raise RuntimeError("Transactions require a configured driver")
        await driver.init()
        connection = await driver.acquire_connection()
        try:
            await connection.begin()
        except BaseException:
            await driver.release_connection(connection)
            raise
        self._connection = connection
        return Pysely[DatabaseT].from_executor(
            self._executor.with_connection(connection), self._schema
        )

    async def __aexit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        traceback: TracebackType | None,
    ) -> None:
        driver = self._executor.driver
        connection = self._connection
        if driver is None or connection is None:
            return
        try:
            if exc_type is None:
                try:
                    await connection.commit()
                except BaseException:
                    await connection.rollback()
                    raise
            else:
                await connection.rollback()
        finally:
            await driver.release_connection(connection)
            self._connection = None


class ConnectionContext(Generic[DatabaseT]):
    def __init__(self, executor: QueryExecutor, schema: Schema | None = None) -> None:
        self._executor = executor
        self._schema = schema
        self._connection: DatabaseConnection | None = None

    async def __aenter__(self) -> Pysely[DatabaseT]:
        driver = self._executor.driver
        if driver is None:
            raise RuntimeError("Connection scopes require a configured driver")
        await driver.init()
        self._connection = await driver.acquire_connection()
        return Pysely[DatabaseT].from_executor(
            self._executor.with_connection(self._connection), self._schema
        )

    async def __aexit__(self, *exc_info: object) -> None:
        driver = self._executor.driver
        connection = self._connection
        if driver is None or connection is None:
            return
        try:
            await driver.release_connection(connection)
        finally:
            self._connection = None


@overload
def Database(  # type: ignore[overload-overlap]
    *,
    schema: type[GeneratedSchema[ClientT]],
    dialect: Dialect,
    plugins: tuple[QueryPlugin, ...] = (),
) -> ClientT: ...


@overload
def Database(
    *,
    schema: type[SchemaT],
    dialect: Dialect,
    plugins: tuple[QueryPlugin, ...] = (),
) -> Pysely[SchemaT]: ...


def Database(
    *,
    schema: type[Any],
    dialect: Dialect,
    plugins: tuple[QueryPlugin, ...] = (),
) -> Any:
    """Build a client for a schema.

    A schema written by `pysely codegen` names its typed client, and that
    client is returned. Any other annotated schema gets a plain `Pysely` with
    runtime validation only.
    """
    client = getattr(schema, "__pysely_client__", None)
    if client is not None:
        return client(dialect=dialect, schema=schema, plugins=plugins)
    return Pysely(dialect=dialect, schema=schema, plugins=plugins)

